(()=>{const e=[["✦","Flowing line","Notice how a single raised line bends into petals, leaves and ornamental curves."],["❋","Floral field","Look for repeated flowers, leaves and vines that create rhythm across the textile."],["◈","Symmetry","Many compositions use half-patterns and mirrored forms to create visual balance."],["●","Pigment texture","The dense paste gives the painted line a tactile quality unlike ordinary flat printing."],["✺","Colour contrast","Bright pigments can be placed against dark cloth so motifs become highly visible."],["⌘","Craft detail","Fine points, joins and controlled curves reveal the precision required."]];document.getElementById("steps").innerHTML=[["01","Prepare the pigment","Castor oil and pigments are worked into a thick, elastic paste suitable for drawing."],["02","Condition the paste","The material is cooled and handled until it reaches a dense workable consistency."],["03","Draw with a stylus","An artisan places and pulls the paste across cloth to create fine lines, dots and forms."],["04","Build the composition","Floral and geometric elements are arranged into balanced and often mirrored patterns."]].map(e=>`<article class="card"><span class="eyebrow">${e[0]}</span><h3>${e[1]}</h3><p>${e[2]}</p></article>`).join(""),document.getElementById("gallery-grid").innerHTML=e.map((e,t)=>`<button class="gallery-item" type="button" data-index="${t}"><div class="gallery-art">${e[0]}</div><strong>${e[1]}</strong><p>${e[2]}</p></button>`).join("");const t=document.getElementById("gallery-detail");document.querySelectorAll(".gallery-item").forEach(a=>a.addEventListener("click",()=>{const n=e[Number(a.dataset.index)];t.innerHTML=`<h3>${n[0]} ${n[1]}</h3><p>${n[2]}</p><p class="muted">Visual study selected. Add an approved historical photograph or artwork asset when repository-approved media is available.</p>`,t.classList.add("active")})),document.getElementById("motif-grid").innerHTML=[["🌺","Flowers","Petals and stylised floral clusters create a central visual vocabulary."],["🌿","Leaves and vines","Curving stems connect elements into a continuous decorative field."],["🦚","Peacock forms","Bird imagery, including the peacock, appears in decorative Rogan compositions."],["☀️","Tree of Life","Branching forms and symmetrical growth are associated with celebrated Rogan designs."],["◈","Geometric rhythm","Dots, diamonds, borders and repeated shapes give compositions structure."],["🌀","Free-flowing ornament","The medium allows artisans to create elegant curves directly on fabric."]].map(e=>`<article class="card"><div style="font-size:2rem">${e[0]}</div><h3>${e[1]}</h3><p>${e[2]}</p></article>`).join(""),document.getElementById("references-list").innerHTML=[["Ministry of Textiles — Handicrafts","Government information on Indian handicrafts and traditional craft traditions.","https://handicrafts.nic.in/"],["Gujarat Tourism","Regional cultural and tourism information about Gujarat crafts and heritage.","https://www.gujarattourism.com/"],["Indian Culture Portal","Government-supported cultural collections and heritage resources.","https://indianculture.gov.in/"],["Crafts Council of India","Resources and advocacy relating to Indian craft traditions and artisans.","https://www.craftscouncilofindia.in/"]].map(e=>`<article class="reference"><h3>${e[0]}</h3><p>${e[1]}</p><a href="${e[2]}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join("");const a=document.getElementById("menu-toggle"),n=document.getElementById("nav-menu");a&&n&&(a.onclick=()=>n.classList.toggle("active")),document.querySelectorAll(".section-nav a").forEach(e=>e.onclick=t=>{const a=document.querySelector(e.getAttribute("href"));a&&(t.preventDefault(),a.scrollIntoView({behavior:"smooth"}))}),window.Journey?.registerSearchItems&&window.Journey.registerSearchItems("rogan-art-explorer/index.html",[{id:"rogan-art",title:"Rogan Art",description:"Explore Gujarat's Rogan art, technique, motifs and artisan heritage.",link:"rogan-art-explorer/index.html"}])})();